@php $rate=$summary['all']?round($summary['active']/$summary['all']*100):0; $used=$coupons->getCollection()->sum('used_count'); @endphp
<div class="admin-page flex"><section class="admin-page-main min-w-0 flex-1"><header class="admin-page-head"><div class="flex items-start justify-between"><h1 class="admin-page-title">Coupons</h1><a href="{{ route('admin.coupons.create') }}" class="admin-action admin-action-dark">＋ Create coupon</a></div><div class="admin-filter-row"><select wire:model.live="status" class="admin-filter {{ $status!=='all'?'is-active':'' }}"><option value="all">All coupons</option><option value="active">Active</option><option value="scheduled">Scheduled</option><option value="expired">Expired</option><option value="inactive">Inactive</option></select><select wire:model.live="discountType" class="admin-filter"><option value="all">Discount type</option><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select><select wire:model.live="sort" class="admin-filter"><option value="newest">Updated</option><option value="ending">Ending soon</option><option value="usage_desc">Most used</option></select><label class="admin-filter min-w-52"><span>⌕</span><input wire:model.live.debounce.350ms="search" class="border-0 bg-transparent p-0 text-[11px] ring-0 focus:ring-0" placeholder="Search coupons"></label></div></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th class="w-10 pl-6"></th><th>Coupon</th><th>Discount</th><th>Minimum</th><th>Usage</th><th>Validity</th><th>Status</th><th class="w-24"></th></tr></thead><tbody>@forelse($coupons as $coupon)@php $life=!$coupon->is_active?'inactive':($coupon->start_date->isFuture()?'scheduled':($coupon->isValidNow()?'active':'expired')); @endphp<tr><td class="pl-6"><input type="checkbox" wire:model.live="selected" value="{{ $coupon->id }}"></td><td><strong class="font-mono">{{ $coupon->code }}</strong><small class="block text-black/35">{{ $coupon->description?:'Promotion code' }}</small></td><td class="font-medium">{{ $coupon->discount_type==='percentage'?rtrim(rtrim($coupon->discount_value,'0